import{_ as o,o as i,c as a,a2 as t}from"./chunks/framework.BN2sqjC1.js";const v=JSON.parse('{"title":"Design crittografico dei vault privati: pacchetto per la revisione esterna","description":"","frontmatter":{},"headers":[],"relativePath":"security/crypto-design.md","filePath":"security/crypto-design.md"}'),n={name:"security/crypto-design.md"};function r(c,e,l,s,d,p){return i(),a("div",null,[...e[0]||(e[0]=[t(`<h1 id="design-crittografico-dei-vault-privati-pacchetto-per-la-revisione-esterna" tabindex="-1">Design crittografico dei vault privati: pacchetto per la revisione esterna <a class="header-anchor" href="#design-crittografico-dei-vault-privati-pacchetto-per-la-revisione-esterna" aria-label="Permalink to &quot;Design crittografico dei vault privati: pacchetto per la revisione esterna&quot;">​</a></h1><p>Stato: preparazione all&#39;audit esterno (M7-WP2). <strong>Non è stato eseguito alcun audit o penetration test</strong>: questo documento e i test collegati servono a metterne un terzo nelle condizioni di farlo in tempi brevi. Riferimenti normativi interni: <code>Specifications.md</code> §3.8 (D-02), ADR-0011, ADR-0012.</p><p>Ogni affermazione è verificata sul codice; i percorsi sono relativi alla radice del repository. Aggiornato il 2026-11-01 con l&#39;envelope v2 (ADR-0034, rilascio N), la normalizzazione NFC della passphrase, i token di path <code>enc2</code> legati al file (ADR-0042, rilascio N), l&#39;igiene delle chiavi in memoria e il tetto della calibrazione di Argon2id; il 2026-11-02 con il rilascio N+1 dei due ADR (formati v2 accesi per default, migrazione dei token <code>enc1</code> e pin forte); il 2026-11-03 con la politica della passphrase applicata dal core (ADR-0045 §8).</p><h2 id="_1-perimetro-e-risorse-da-proteggere" tabindex="-1">1. Perimetro e risorse da proteggere <a class="header-anchor" href="#_1-perimetro-e-risorse-da-proteggere" aria-label="Permalink to &quot;1. Perimetro e risorse da proteggere&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Risorsa</th><th>Dove vive</th><th>Protezione</th></tr></thead><tbody><tr><td>Contenuto dei file di un vault privato</td><td>Blob su S3, sul client in chiaro</td><td>AES-256-GCM a chunk (<code>shared/go/vaultcrypto/blob.go</code>)</td></tr><tr><td>Path dei file</td><td>Colonne <code>files.path</code>, <code>file_revisions.path</code></td><td><code>enc1:</code>/<code>enc2:</code> AES-256-GCM; unicità via <code>hmac1:</code> (<code>path.go</code>)</td></tr><tr><td>VMK (Vault Master Key, 256 bit)</td><td>Mai sul server in chiaro; keychain del SO sui client</td><td>Avvolta in due envelope (<code>vault_key_envelopes</code>)</td></tr><tr><td>Passphrase e recovery key</td><td>Solo nella testa/nei supporti dell&#39;utente</td><td>Mai trasmesse; solo KEK derivate localmente</td></tr><tr><td>Metadati (nome vault, dimensioni, conteggi, tempi)</td><td>Database del server</td><td><strong>Non protetti</strong> (§6)</td></tr></tbody></table><p>Fuori perimetro della crittografia: vault condivisi (non E2EE, D-02), cifratura a riposo del disco del dispositivo (§3.8.6 dello spec), autenticazione OIDC.</p><h2 id="_2-confini-di-fiducia" tabindex="-1">2. Confini di fiducia <a class="header-anchor" href="#_2-confini-di-fiducia" aria-label="Permalink to &quot;2. Confini di fiducia&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span> Dispositivo utente (fidato)      |  Rete (TLS)  |  Server cloud + PG + S3 (non fidato per il contenuto)</span></span>
<span class="line"><span> passphrase, recovery key, VMK,   |              |  vede: ciphertext, path_enc, path_key, envelope,</span></span>
<span class="line"><span> plaintext, indici locali         |              |  dimensioni, tempi, id utente/dispositivo</span></span>
<span class="line"><span>                                  |              |</span></span>
<span class="line"><span> Browser (Web UI)  — fidato solo nella misura in cui lo è il JavaScript servito dal server stesso</span></span></code></pre></div><ul><li>Il server è autorità per ordine delle modifiche, quote e ACL; <strong>non interpreta mai</strong> il contenuto (il merge è sul client). Un server compromesso può rifiutare il servizio, ritardare, cancellare o riproporre revisioni vecchie, ma non leggere né alterare in modo non rilevabile i contenuti di un vault privato.</li><li>Un server malevolo può servire JavaScript alterato alla Web UI e ottenere passphrase/VMK in quel browser. Il client desktop firmato (M7-WP3) è il livello di fiducia massimo.</li></ul><h2 id="_3-modello-di-minaccia-§3-8-1-dello-spec-riformulato" tabindex="-1">3. Modello di minaccia (§3.8.1 dello spec, riformulato) <a class="header-anchor" href="#_3-modello-di-minaccia-§3-8-1-dello-spec-riformulato" aria-label="Permalink to &quot;3. Modello di minaccia (§3.8.1 dello spec, riformulato)&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td>Protegge da</td><td>Lettura di contenuti e path da parte di amministratori, operatori, leak del database o del bucket, compromissione del server.</td></tr><tr><td>Non protegge da</td><td>Compromissione del dispositivo; metadati osservabili dal server; server che serve JS alterato alla Web UI; attacco offline alla passphrase da chi ottenga database <strong>e</strong> un token dell&#39;owner (l&#39;envelope passphrase sta sul server: trade-off dichiarato, O-03).</td></tr><tr><td>Fuori ambito</td><td>Condivisione di vault cifrati (rifiutata con <code>VAULT_ENCRYPTED</code>, anche da trigger DB <code>shares_vault_kind_chk</code>, migrazione <code>0004</code>); rotazione della VMK (post-1.0).</td></tr></tbody></table><p>Avversari considerati: (A1) amministratore o operatore curioso, (A2) chi esfiltra DB e bucket, (A3) server attivamente malevolo (sostituzione, riordino, troncamento, replay di blob), (A4) attaccante di rete oltre TLS (coperto da TLS e dall&#39;AEAD), (A5) attaccante con il solo token dell&#39;owner (può scaricare gli envelope: attacco offline alla passphrase, mitigato da Argon2id).</p><h2 id="_4-gerarchia-delle-chiavi" tabindex="-1">4. Gerarchia delle chiavi <a class="header-anchor" href="#_4-gerarchia-delle-chiavi" aria-label="Permalink to &quot;4. Gerarchia delle chiavi&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>passphrase ──Argon2id(t,m,p,salt)──► KEK_pass ─┐</span></span>
<span class="line"><span>                                               ├─ AES-256-GCM unwrap ─► VMK (256 bit CSPRNG, una per vault)</span></span>
<span class="line"><span>recovery key ──HKDF-SHA256(salt)───► KEK_rec  ─┘                          │</span></span>
<span class="line"><span>                                                                          ├─ HKDF(&quot;memobrain/v1/path-enc&quot;) → K_path_enc</span></span>
<span class="line"><span>                                                                          ├─ HKDF(&quot;memobrain/v1/path-key&quot;) → K_path_key</span></span>
<span class="line"><span>                                                                          └─ HKDF(&quot;memobrain/v1/file&quot; ‖ file_id ‖ salt_file) → K_file</span></span></code></pre></div><p>Implementazione: <code>shared/go/vaultcrypto/keys.go</code> (Go), <code>packages/vaultcrypto-web/src/keys.ts</code> (TypeScript). Le etichette HKDF sono costanti con prefisso di versione (<code>clarae/v1/…</code>) per la separazione di dominio. HKDF-SHA256 senza salt per le sottochiavi: la VMK è già uniforme a 256 bit.</p><ul><li><p><strong>Envelope</strong>: due formati, descritti in §5.3. Il v1 è <code>nonce(12) ‖ AES-256-GCM(KEK, VMK) ‖ tag(16)</code> = 60 byte, senza AAD. Il v2 (ADR-0034) è <code>0x02 ‖ nonce(12) ‖ AES-256-GCM(KEK, VMK; AAD) ‖ tag(16)</code> = 61 byte, legato a <code>vault_id</code> e al tipo di envelope. Nonce casuale: ogni KEK avvolge un solo valore (la VMK), il rischio di collisione è trascurabile.</p></li><li><p><strong>Recovery key</strong>: 256 bit CSPRNG; testo = Base32 (alfabeto RFC 4648) in gruppi da 5 con checksum SHA-256 troncato a 16 bit (<code>&quot;memobrain/v1/recovery-checksum&quot; ‖ chiave</code>). Il checksum rileva refusi, non è un controllo di sicurezza. KEK_rec = HKDF(recovery key, salt dell&#39;envelope): nessuno stretching, la chiave ha già piena entropia.</p></li><li><p><strong>Passphrase</strong>: minimo 12 caratteri e zxcvbn ≥ 3 (§3.8.2), imposti dal <strong>core Go</strong> a ogni passphrase nuova (sotto); il server non può verificarli. Prima di Argon2id la passphrase si normalizza in Unicode <strong>NFC</strong> (§5.4), così la stessa passphrase digitata con caratteri composti o scomposti (tastiere e sistemi operativi diversi) deriva la stessa KEK.</p></li><li><p><strong>Cache locale della VMK</strong>: keychain del sistema operativo (<code>apps/desktop/internal/crypto/keystore.go</code>); la Web UI non la persiste.</p></li><li><p><strong>Igiene delle chiavi in memoria</strong> (best effort):</p><ul><li>un vault sbloccato tiene un solo <code>*Subkeys</code> (<code>apps/desktop/internal/crypto/manager.go</code>), che contiene l&#39;unica copia di lunga durata della VMK; le sottochiavi si passano per puntatore, non più per valore;</li><li>al blocco (manuale, per inattività o allo scollegamento) <code>Subkeys.Wipe</code> azzera <code>K_path_enc</code>, <code>K_path_key</code> e la VMK. Un <code>RWMutex</code> per vault fa sì che il blocco aspetti le operazioni in corso; un&#39;operazione che parte dopo riceve <code>ErrLocked</code>. Le funzioni di <code>vaultcrypto</code> rifiutano sottochiavi azzerate (<code>ErrWiped</code>): nulla viene mai cifrato con una chiave a zero;</li><li>la libreria azzera i propri buffer intermedi appena copiati (uscite di Argon2id e HKDF, <code>K_file</code>, VMK decifrata); il gestore delle chiavi azzera KEK e copie della VMK dopo wrap, unwrap e verifica; <code>Material.Wipe</code> azzera il materiale di creazione;</li><li><strong>limiti di Go</strong>: il runtime può aver già copiato un array (passaggio per valore, crescita dello stack, spostamenti del garbage collector); lo schedule AES dentro <code>crypto/cipher</code>, le stringhe immutabili (passphrase, VMK in base64 verso il keychain) e la memoria lineare del WASM non si possono azzerare. Lo scopo è avere meno copie vive per meno tempo, non una garanzia (§8).</li></ul></li><li><p><strong>Dove si applica la politica della passphrase</strong> (ADR-0045 §8). <code>crypto.ValidatePassphrase</code> (<code>apps/desktop/internal/crypto/policy.go</code>) è il controllo, nel core, di ogni binding che imposta una passphrase nuova: creazione di un vault privato (<code>SyncAPI.LinkNew</code> → <code>sync.Manager.Link</code>, poi <code>crypto.Manager.NewMaterial</code>), cambio di passphrase (<code>VaultCryptoAPI.ChangePassphrase</code>) e passphrase nuova dopo la recovery key (<code>VaultCryptoAPI.SetPassphrase</code>, anche dal gate di sblocco del web), tutti con un secondo controllo in <code>crypto.Manager.NewPassphraseEnvelope</code>. Sono gli unici punti che avvolgono la VMK sotto una passphrase scelta dall&#39;utente; il browser non crea envelope (<code>packages/vaultcrypto-web</code> li apre soltanto, per lo ZIP). Il controllo avviene prima della rete e prima della verifica della vecchia passphrase; il rifiuto è l&#39;errore tipizzato <code>weak-passphrase: &lt;motivo&gt;: &lt;testo&gt;</code> con motivo <code>too-short</code> o <code>guessable</code>, che il workbench traduce (<code>errorMessage</code>, chiavi <code>errors.weak-passphrase_&lt;motivo&gt;</code>) e il gate DOM del web pure (<code>gateErrorText</code>). La regola, sulla forma NFC:</p><ul><li>almeno 12 code point (<code>MinPassphraseLength</code>); una stringa UTF-8 non valida è rifiutata come troppo corta;</li><li>punteggio zxcvbn ≥ 3 (<code>MinPassphraseScore</code>), stimato sui primi 64 code point (<code>MaxEstimatedLength</code>; <code>strength.ts</code> legge lo stesso prefisso): il confronto con i dizionari è quadratico nei byte, e 256 caratteri CJK o emoji costavano secondi già in nativo, 64 restano sotto i 30 ms; una passphrase i cui primi 64 caratteri sono deboli è debole. Lo stimatore Go è <code>github.com/trustelem/zxcvbn</code> v1.0.1 (MIT, Go puro, compila per <code>js/wasm</code>), un port completo di zxcvbn 4.4.2: lo stesso algoritmo basato sui tentativi di <code>@zxcvbn-ts</code>, con dizionari leggermente diversi. Il port <code>ccojocar/zxcvbn-go</code>, più aggiornato, è stato scartato perché usa il punteggio del vecchio zxcvbn (tempi di attacco, soglia del 3 circa cento volte più alta) e rifiuterebbe passphrase che la UI accetta. Su una passphrase al limite i due lati possono quindi dare 2 e 3; i casi su cui devono concordare stanno in <code>shared/conformance/passphrase/policy.json</code>, eseguito sia dai test Go (<code>policy_test.go</code>) sia da quelli TS (<code>strength.test.ts</code>). Divergenza nota: le ripetizioni con separatori (<code>dragon-dragon</code>) valgono 3 per il port Go e 0 per <code>@zxcvbn-ts</code>, quindi la UI resta più severa del core in quei casi;</li><li>costo nel core WebAssembly: circa +0,8 MB gzip (dizionari e <code>dlclark/regexp2</code>), circa 35 ms e 10 MB di heap all&#39;avvio del worker per costruire i dizionari ordinati.</li></ul><p>React (<code>PassphraseFields</code>) e il gate DOM tengono il riscontro immediato con <code>@zxcvbn-ts</code> (<code>strength.ts</code>, ora anch&#39;esso sulla forma NFC) ma non sono più l&#39;unica difesa. <strong>La politica vale solo per le passphrase nuove</strong>: sbloccare, verificare la vecchia passphrase, rigenerare la recovery key e riavvolgere in v2 l&#39;envelope aperto non la controllano, quindi un vault creato con una regola più debole (solo lunghezza, fino alla 1.3) resta apribile; al primo cambio la passphrase nuova deve rispettarla (<code>TestPolicyIsNotAppliedToExistingPassphrases</code>).</p></li><li><p><strong>Cambio passphrase / recovery key</strong>: nuovo envelope della stessa VMK, nessuna ri-cifratura dei dati. Il formato del nuovo envelope segue le regole di migrazione di §5.3. Dopo un cambio, i vecchi envelope scaricati prima restano validi per chi conosceva la vecchia passphrase: senza rotazione della VMK una passphrase compromessa resta utile contro ciò che l&#39;attaccante ha già copiato (§6).</p></li></ul><h2 id="_5-formati" tabindex="-1">5. Formati <a class="header-anchor" href="#_5-formati" aria-label="Permalink to &quot;5. Formati&quot;">​</a></h2><h3 id="_5-1-blob-nds1-§3-8-3" tabindex="-1">5.1 Blob <code>NDS1</code> (§3.8.3) <a class="header-anchor" href="#_5-1-blob-nds1-§3-8-3" aria-label="Permalink to &quot;5.1 Blob \`NDS1\` (§3.8.3)&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>header : &quot;NDS1&quot; | versione (1 B) | salt_file (16 B) | chunk_size (4 B big endian)      = 25 B</span></span>
<span class="line"><span>corpo  : chunk_0 ‖ … ‖ chunk_n        ogni chunk = ciphertext ‖ tag GCM (16 B)</span></span>
<span class="line"><span>nonce  : 96 bit, contatore big endian = indice del chunk</span></span>
<span class="line"><span>AAD    : vault_id (16) ‖ file_id (16) ‖ indice (8, big endian) ‖ flag &quot;ultimo chunk&quot; (1)</span></span></code></pre></div><ul><li><code>chunk_size</code> ∈ [1, 16 MiB]; ogni chunk salvo l&#39;ultimo ha esattamente <code>chunk_size</code> byte, l&#39;ultimo ne ha 1..<code>chunk_size</code> (file vuoto = un chunk vuoto). Il cifratore legge un chunk in anticipo per sapere quale è l&#39;ultimo (<code>blob.go</code>).</li><li>Una nuova <code>salt_file</code> casuale per ogni cifratura produce una nuova <code>K_file</code>: i nonce a contatore non si ripetono mai sotto la stessa chiave.</li><li>L&#39;AAD lega il chunk a vault, file, posizione e fine-file: scambio tra file o vault, riordino, duplicazione, troncamento al confine di chunk e aggiunta di chunk sono rilevati. L&#39;header non è autenticato direttamente: <code>salt_file</code> altera <code>K_file</code> (decifratura fallisce), <code>chunk_size</code> altera il parsing (fallisce), <code>versione</code> ≠ 1 è rifiutata.</li><li><code>blob_hash</code> = SHA-256 del blob <strong>cifrato</strong> (integrità del trasferimento, non del contenuto). Il server accetta un blob per un vault solo se lo ha caricato quel vault (<code>vault_blobs</code>), così <code>blobs:check</code> non rivela cosa conservano altri.</li></ul><h3 id="_5-2-path-§3-8-3" tabindex="-1">5.2 Path (§3.8.3) <a class="header-anchor" href="#_5-2-path-§3-8-3" aria-label="Permalink to &quot;5.2 Path (§3.8.3)&quot;">​</a></h3><ul><li><code>path_enc</code> = <code>&quot;enc1:&quot; + base64url(nonce(12) ‖ AES-256-GCM(K_path_enc, path NFC; AAD = vault_id))</code>, nonce casuale.</li><li><code>path_key</code> = <code>&quot;hmac1:&quot; + hex(HMAC-SHA256(K_path_key, NFC + casefold(path)))</code>, deterministico, usato dal server per l&#39;unicità (<code>PATH_COLLISION</code>) senza conoscere il path. Rivela l&#39;uguaglianza di due path (es. lo stesso path nelle revisioni successive) ma non il contenuto.</li><li>Con nonce casuali a 96 bit e una sola <code>K_path_enc</code> per vault, il limite di sicurezza di AES-GCM (≈ 2^32 cifrature) è molto sopra il numero di path realistico per vault; è un limite noto, non una vulnerabilità pratica.</li></ul><p><strong>Token <code>enc2</code> legati al file (ADR-0042).</strong> <code>enc1</code> lega il path solo al vault: un server malevolo potrebbe associare al file X il token del file Y dello stesso vault. Il formato <code>enc2</code> lega il token anche al file:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>enc2 : &quot;enc2:&quot; + base64url(nonce (12) ‖ AES-256-GCM(K_path_enc, path NFC; AAD) ‖ tag (16))</span></span>
<span class="line"><span>AAD  : &quot;memobrain/v2/path&quot; (17 B ASCII) ‖ vault_id (16 B) ‖ file_id (16 B)</span></span></code></pre></div><ul><li>Stessa chiave e stesso nonce casuale di <code>enc1</code>; le due AAD differiscono per lunghezza e prefisso, quindi un token rietichettato da una versione all&#39;altra non si apre. <code>path_key</code> (<code>hmac1</code>) non cambia: unicità e <code>PATH_COLLISION</code> restano identiche in un vault misto.</li><li><strong>Lettura</strong>: <code>DecryptPathFor(sub, vault_id, file_id, token)</code> in Go e <code>decryptPathFor</code> in TS accettano i due formati; il motore di sync e l&#39;export ZIP passano il <code>file_id</code> della change o della voce del manifest. Un <code>enc2</code> di un altro file o vault è <code>ErrDecrypt</code>/<code>DecryptError</code>: la change va in quarantena e il file locale non viene toccato.</li><li><strong>Prima di cifrare</strong> un path il client applica la regola completa dei nomi riservati di Windows (<code>pathrules.NormalizePortable</code>), che per i vault privati il server non può controllare.</li><li><strong>Pinning</strong> (client desktop e core WASM): <code>path_v2:&lt;id cloud&gt;</code> in <code>sync.db</code> annota che il vault ha token <code>enc2</code> (visti o scritti e accettati) e da lì i nuovi token restano <code>enc2</code>; <code>path_v2_file:&lt;file_id&gt;</code> annota il singolo file e da lì un suo token <code>enc1</code> è rifiutato (<code>ErrPathDowngrade</code>, quarantena); <code>path_v2_strong:&lt;id cloud&gt;</code> (pin forte, sotto) fa rifiutare ogni token <code>enc1</code> del vault.</li><li><strong>Stato della migrazione: rilascio N+1 (2026-11-02).</strong><ul><li>Tutti i client leggono <code>enc1</code> ed <code>enc2</code>; il server accetta i due prefissi (<code>resolvePath</code>).</li><li>Si scrive <code>enc2</code> per default: <code>features.path_v2</code> è acceso nello schema del Config Profile. Un amministratore può spegnerlo; un vault annotato continua comunque a scrivere <code>enc2</code>.</li><li><strong>Migrazione dei token rimasti <code>enc1</code></strong> (<code>apps/desktop/internal/sync/pathmigrate.go</code>), solo con il flag acceso e il vault sbloccato. Il client riscrive il token come <code>enc2</code> con un <code>move</code> verso lo stesso path: stesso <code>hmac1</code>, <code>base_rev</code> del file, contenuto invariato. Il server accetta un move sul <code>path_key</code> del file stesso (<code>move</code> in <code>services/cloud/internal/sync/ops.go</code>, test <code>TestPrivateVaultAcceptsEnc2PathTokens</code>).</li><li>La migrazione gira solo alla fine di un ciclo di sync che non ha trovato altro da fare: un lotto per ciclo (100 file), almeno 15 s tra due lotti, 30 s al massimo per lotto. Tocca solo i file sincronizzati alla revisione dell&#39;albero, senza modifiche locali, candidati al merge o errori, e il cui path decifrato coincide con quello locale. Un conflitto lascia il file a un passaggio successivo, e un errore non fa mai fallire il ciclo.</li><li>Il progresso sta nell&#39;albero del server, più i contatori e l&#39;ora del lotto successivo in <code>sync.db</code> (<code>path_v2_migration:&lt;id cloud&gt;</code>): dopo un riavvio la migrazione riprende.</li><li><strong>Pin forte</strong>: quando un albero completo (<code>GET /tree</code>) ha almeno un file e nessun token <code>enc1</code>, e il cursore del client ha raggiunto il suo <code>as_of_seq</code>, il client annota <code>path_v2_strong:&lt;id cloud&gt;</code>. Da lì rifiuta ogni token <code>enc1</code> del vault: change in quarantena (ADR-0039), file locale intatto.</li><li>L&#39;export ZIP del browser, senza stato, continua ad accettare <code>enc1</code>.</li></ul></li></ul><h3 id="_5-3-envelope-della-vmk-v1-e-v2-adr-0034" tabindex="-1">5.3 Envelope della VMK: v1 e v2 (ADR-0034) <a class="header-anchor" href="#_5-3-envelope-della-vmk-v1-e-v2-adr-0034" aria-label="Permalink to &quot;5.3 Envelope della VMK: v1 e v2 (ADR-0034)&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>v1 : nonce (12) ‖ AES-256-GCM(KEK, VMK) ‖ tag (16)                         = 60 B, nessun AAD</span></span>
<span class="line"><span>v2 : 0x02 ‖ nonce (12) ‖ AES-256-GCM(KEK, VMK; AAD) ‖ tag (16)              = 61 B</span></span>
<span class="line"><span>AAD: &quot;memobrain/v2/envelope&quot; (21 B ASCII) ‖ vault_id (16 B) ‖ kind (&quot;passphrase&quot; | &quot;recovery&quot;, ASCII)</span></span></code></pre></div><ul><li><strong>Lettura</strong> (<code>Unwrap(kek, wrapped, vaultID, kind)</code> in Go, <code>unwrap(kek, wrapped, vaultId, kind)</code> in TS): 60 byte → v1; 61 byte con primo byte <code>0x02</code> → v2 con AAD obbligatoria; qualunque altra lunghezza o byte di versione → <code>ErrDecrypt</code>/<code>DecryptError</code>. Un v2 servito per un altro vault o come altro tipo non si apre e appare come passphrase sbagliata. Il downgrade non è possibile: il corpo di un v2 privato del byte di versione non si apre come v1, perché il tag GCM copre l&#39;AAD.</li><li><strong>Server</strong>: <code>vaults.ValidateEnvelope</code> accetta 60 byte, oppure 61 byte che iniziano con <code>0x02</code>; non interpreta altro.</li><li><strong>Pinning</strong> (solo client desktop e core WASM; l&#39;export ZIP del browser non ha stato persistente): dopo aver aperto o caricato un envelope v2 di un certo tipo, il client lo annota in <code>sync.db</code> (<code>envelope_v2:&lt;id cloud&gt;:&lt;kind&gt;</code>) e da quel momento rifiuta un v1 di quel tipo per quel vault (<code>ErrEnvelopeDowngrade</code>). Il pin è per tipo, perché l&#39;envelope di recovery resta v1 finché non si usa la recovery key.</li><li><strong>Stato della migrazione: rilascio N+1 (2026-11-02).</strong><ul><li>Tutti i client leggono v1 e v2: desktop, core WASM del workbench web, <code>vaultcrypto-web</code> dell&#39;export ZIP.</li><li><code>features.envelope_v2</code> è acceso per default nello schema del Config Profile; un amministratore può spegnerlo. Con il flag acceso: <ul><li>v2 alla creazione (subito dopo, perché l&#39;id del vault lo assegna il server) e a ogni cambio di passphrase o di recovery key;</li><li>upgrade a v2 dell&#39;envelope aperto allo sblocco, con la passphrase o con la recovery key;</li><li>caricamento best effort, solo se l&#39;envelope sul server è ancora quello aperto.</li></ul></li><li>Indipendentemente dal flag, un tipo di envelope già v2 non torna mai v1.</li><li>ADR-0034 non prevede un pin forte: un envelope di recovery mai usato resta v1, e si apre, finché l&#39;utente non usa o non rigenera la recovery key.</li><li>I desktop fino alla 1.2.4 non aprono un envelope v2 (guida admin, <code>backup-upgrade.md</code>).</li></ul></li></ul><h3 id="_5-4-normalizzazione-della-passphrase" tabindex="-1">5.4 Normalizzazione della passphrase <a class="header-anchor" href="#_5-4-normalizzazione-della-passphrase" aria-label="Permalink to &quot;5.4 Normalizzazione della passphrase&quot;">​</a></h3><ul><li><strong>Scrittura</strong>: <code>DeriveKEKPassphrase</code> (Go) e <code>deriveKekPassphrase</code> (TS) derivano la KEK dalla forma NFC della passphrase. È la regola di ogni envelope nuovo: creazione, cambio passphrase, nuova passphrase dopo la recovery.</li><li><strong>Lettura</strong> (<code>OpenWithPassphrase</code> / <code>openWithPassphrase</code>): si provano in ordine la forma NFC, l&#39;input esatto e la sua forma NFD, senza duplicati (<code>PassphraseForms</code> / <code>passphraseForms</code>). Gli envelope scritti prima della normalizzazione, dai byte grezzi di un input non NFC, continuano così ad aprirsi, anche da un dispositivo che produce l&#39;altra forma. Una passphrase ASCII costa una sola derivazione; una passphrase sbagliata con caratteri scomponibili ne costa fino a tre.</li><li><strong>Convergenza</strong>: un envelope aperto solo con una forma legacy viene ri-avvolto sotto la forma NFC, con gli stessi parametri KDF, solo con <code>features.envelope_v2</code> acceso (nell&#39;upgrade a v2). Con il flag spento resta com&#39;è, perché un client anteriore a questa versione deve poterlo ancora aprire digitando la stessa forma non NFC.</li><li><strong>Recovery key</strong>: invariata. Alfabeto Base32 ASCII con checksum: un carattere non ASCII fa fallire il parsing prima di qualsiasi derivazione, quindi non serve normalizzare.</li><li><strong>Limite</strong>: NFC dipende dalla versione Unicode dell&#39;implementazione (<code>golang.org/x/text</code> in Go, il motore JavaScript nel browser). Per i caratteri già assegnati la normalizzazione è stabile; un carattere assegnato solo nelle versioni più recenti potrebbe normalizzarsi in modo diverso tra due client di epoche diverse. È un caso marginale, e il fallback sull&#39;input esatto lo copre quando l&#39;input è identico.</li></ul><h2 id="_6-parametri-e-minimi" tabindex="-1">6. Parametri e minimi <a class="header-anchor" href="#_6-parametri-e-minimi" aria-label="Permalink to &quot;6. Parametri e minimi&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Parametro</th><th>Valore</th><th>Dove è imposto</th></tr></thead><tbody><tr><td>Argon2id minimo</td><td>t=3, m=64 MiB, p=4</td><td>Go: <code>keys.go</code> (<code>MinT</code>, <code>MinMKiB</code>, <code>MinP</code>); TS: <code>keys.ts</code>; server: <code>vaults.ValidateEnvelope</code> (<code>services/cloud/internal/vaults/service.go</code>)</td></tr><tr><td>Argon2id massimo</td><td>t=12, m=1 GiB, p=16</td><td>idem (protegge il client da envelope ostili che causerebbero DoS)</td></tr><tr><td>Calibrazione</td><td>memoria raddoppiata fino a ≈ tempo-bersaglio, mai oltre 256 MiB (<code>MaxCalibratedMKiB</code>, <code>CalibratePassphraseKDF</code>)</td><td>salvata nell&#39;envelope, usata da ogni dispositivo</td></tr><tr><td>Salt KDF</td><td>≥ 8 byte (generati 16)</td><td>client e server</td></tr><tr><td><code>WeakKdfError</code> / <code>ErrWeakKDF</code></td><td>un envelope con parametri sotto il minimo o sopra il massimo, algoritmo diverso o salt non valido <strong>non viene derivato</strong>: un server ostile non può declassare l&#39;Argon2id</td><td><code>DeriveKEKPassphrase</code> (Go), <code>deriveKekPassphrase</code> (TS)</td></tr><tr><td>Chunk</td><td>default 64 KiB, max 16 MiB</td><td><code>blob.go</code>, <code>blob.ts</code></td></tr></tbody></table><p>I minimi di Argon2id sono quelli dello spec (t=3, m=64 MiB, p=4); la scelta di parametri più alti è del dispositivo che crea il vault. Non esiste una politica server per alzare i minimi sui vault esistenti.</p><p><strong>Tetto della calibrazione: il client più debole.</strong> I parametri scelti dal dispositivo che crea il vault valgono per tutti i dispositivi che lo aprono. Il più lento è il browser: l&#39;export ZIP della Web UI (<code>hash-wasm</code>) esegue le p corsie una dopo l&#39;altra in WebAssembly a thread singolo e alloca m KiB di memoria lineare, mentre Go le esegue in parallelo. Un vault calibrato su un Mac veloce a 512 MiB richiedeva al browser 512 MiB di memoria WASM e una derivazione diverse volte più lenta. Il tetto è ora 256 MiB (<code>MaxCalibratedMKiB</code>): con il tempo-bersaglio di 500 ms su un desktop nativo, il browser resta nell&#39;ordine di pochi secondi e di una quantità di memoria disponibile sulle macchine comuni. La calibrazione stessa esegue al più due derivazioni di prova (64 e 128 MiB). Gli envelope esistenti non cambiano: il massimo accettato in lettura resta 1 GiB, quindi quelli calibrati prima fino a 512 MiB continuano ad aprirsi ovunque; un cambio di passphrase li ricalibra sotto il nuovo tetto.</p><h2 id="_7-cosa-vede-e-non-vede-il-server" tabindex="-1">7. Cosa vede e non vede il server <a class="header-anchor" href="#_7-cosa-vede-e-non-vede-il-server" aria-label="Permalink to &quot;7. Cosa vede e non vede il server&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Vede</th><th>Non vede</th></tr></thead><tbody><tr><td>Ciphertext e relativo SHA-256, dimensioni del ciphertext (≈ plaintext + 16 B/chunk + 25 B)</td><td>Contenuto dei file, VMK, passphrase, recovery key, K_*</td></tr><tr><td><code>path_enc</code> (opaco), <code>path_key</code> (uguaglianza di path)</td><td>Path in chiaro, struttura delle cartelle, estensioni</td></tr><tr><td>Envelope (KDF, salt, wrapped VMK, formato v1/v2)</td><td>KEK</td></tr><tr><td>Nome del vault, <code>kind</code>, numero di file, byte totali, timestamp, sequenza e frequenza delle modifiche, dispositivi, utente autore</td><td>Quali file sono cambiati nel merge, diff, contenuto dello storico</td></tr></tbody></table><p>Un vault privato non è condivisibile: <code>POST /shares</code> risponde <code>409 VAULT_ENCRYPTED</code> e il trigger <code>shares_vault_kind_chk</code> lo vieta anche a livello di database; export ZIP, ricerca e diff si fanno sul client (browser con WebCrypto, <code>packages/vaultcrypto-web/src/export.ts</code>, o desktop).</p><h2 id="_8-limiti-noti-accettati-o-rinviati" tabindex="-1">8. Limiti noti (accettati o rinviati) <a class="header-anchor" href="#_8-limiti-noti-accettati-o-rinviati" aria-label="Permalink to &quot;8. Limiti noti (accettati o rinviati)&quot;">​</a></h2><ol><li><strong>Nessuna rotazione della VMK</strong> (post-1.0): chi ha conosciuto la passphrase e ha copiato envelope e ciphertext può decifrare tutto ciò che ha copiato anche dopo un cambio passphrase. Non c&#39;è forward secrecy per i ciphertext passati se la passphrase viene compromessa.</li><li><strong>Attacco offline alla passphrase</strong> con database + token owner (envelope sul server): mitigato da Argon2id e dalla policy di robustezza applicata dal core del client (§4), non eliminato; un client modificato può ancora scegliere una passphrase debole, perché il server non la vede.</li><li><strong>Metadati</strong>: dimensioni (anche per file), numero di file, timing e frequenza delle modifiche, <code>path_key</code> deterministico, elenco dispositivi, nome del vault.</li><li><strong>Web UI</strong>: la decifratura nel browser si fida del JavaScript servito. CSP e SRI (<code>docs/security/pentest-scope.md</code>, test in <code>services/cloud/web-embed/security_test.go</code> e <code>web/e2e-security</code>) riducono la superficie ma non proteggono da un server che cambia anche l&#39;<code>index.html</code>.</li><li><strong>Dati locali in chiaro</strong> sul dispositivo (<code>index.db</code>, copia del vault): demandati alla cifratura del disco.</li><li><strong>Rollback/ritardo di revisioni</strong>: un server malevolo può nascondere revisioni recenti o riproporne di vecchie (ogni blob è autentico ma l&#39;<em>ordine</em> e la completezza non sono firmati). Non esiste un registro di trasparenza.</li><li><strong>Envelope v1 senza AAD durante la migrazione</strong> (ADR-0034). Gli envelope v1, scritti per default fino al rilascio N, non sono legati a <code>vault_id</code>: un server può scambiare gli envelope di due vault dello stesso utente. La decifratura fallisce o cede la VMK dell&#39;altro vault, mai dati di terzi. Il formato v2 chiude il problema per i vault migrati; il pinning per tipo impedisce di ripresentare un v1 a un dispositivo che ha già visto il v2. Restano esposti i vault ancora v1 e i dispositivi che non hanno mai visto il v2 (primo sblocco, export ZIP del browser), finché un dispositivo con il flag acceso (il default dal rilascio N+1) non sblocca il vault e carica l&#39;upgrade, o se l&#39;amministratore spegne <code>features.envelope_v2</code>. Gli envelope di recovery dei vault mai recuperati restano v1 finché l&#39;utente non usa o non rigenera la recovery key.</li><li><strong>Troncamento in chiaro del file intero</strong>: non rilevabile da chi non conosce lo stato precedente (stesso punto del rollback).</li><li><strong>Cifratura dei metadati dei commit</strong> (<code>op</code>, <code>base_rev</code>, <code>kind</code>): in chiaro per necessità del protocollo (ordinamento e concorrenza ottimistica).</li><li><strong>Token di path <code>enc1</code> non legati al file durante la migrazione</strong> (ADR-0042). Un server malevolo può associare a un file il token <code>enc1</code> di un altro file dello stesso vault: il client scrive il contenuto del primo al path del secondo. Il formato <code>enc2</code> chiude il problema per i file migrati; il pin di file impedisce di ripresentare un <code>enc1</code> per un file già visto in <code>enc2</code>. Restano esposti i file che hanno ancora <code>enc1</code> e che il dispositivo non ha mai visto in <code>enc2</code>, finché la migrazione del rilascio N+1 non li riscrive e un albero senza <code>enc1</code> non accende il pin forte; i vault che nessun dispositivo con il flag acceso sblocca; l&#39;export ZIP del browser (senza stato persistente) per i file <code>enc1</code>. Le revisioni dello storico conservano il token con cui sono state scritte, e un file cancellato prima della migrazione e ripristinato dopo il pin forte torna con il suo ultimo token <code>enc1</code>: i dispositivi con il pin forte lo mettono in quarantena (i dati restano sul server). Il danno resta dentro i dati dell&#39;utente: il server non impara nulla.</li><li><strong>Cancellazione delle chiavi in memoria solo best effort</strong> (§4): Go non garantisce che una chiave non sia stata copiata prima dell&#39;azzeramento, e lo schedule AES, le stringhe e la memoria del WASM non si possono azzerare. Un dump della memoria di un processo con un vault sbloccato espone comunque le chiavi.</li></ol><h2 id="_9-come-go-e-typescript-restano-uguali" tabindex="-1">9. Come Go e TypeScript restano uguali <a class="header-anchor" href="#_9-come-go-e-typescript-restano-uguali" aria-label="Permalink to &quot;9. Come Go e TypeScript restano uguali&quot;">​</a></h2><ul><li><strong>Vettori di conformità positivi</strong>: <code>shared/conformance/crypto/vectors.json</code>, generati dal codice Go (<code>UPDATE_VECTORS=1 go test ./vaultcrypto/</code> in <code>shared/go</code>) e verificati da <code>shared/go/vaultcrypto/vaultcrypto_test.go</code> (<code>TestVectors</code>) e da <code>packages/vaultcrypto-web/src/vectors.test.ts</code>. Coprono: <ul><li>KEK da passphrase (Argon2id) e da recovery key;</li><li>wrap v1 e <code>wrap_v2</code> (passphrase e recovery, con l&#39;AAD in esadecimale);</li><li><code>passphrase_normalization</code>: input NFC e NFD con la stessa KEK, KEK grezza dell&#39;input NFD, un envelope legacy v1 aperto da entrambe le forme, un envelope v2 corrente;</li><li>sottochiavi, blob (vuoto, parziale, esatto, due chunk, chunk di default) e path <code>enc1</code>;</li><li><code>paths_v2</code> (ADR-0042): token <code>enc2</code> con l&#39;AAD in esadecimale, lo stesso path per due <code>file_id</code> diversi, <code>hmac1</code> invariato.</li></ul></li><li><strong>Vettori negativi</strong> (nuovi): <code>shared/conformance/crypto/negative-vectors.json</code>, generati dal Go (<code>TestNegativeVectors</code>, stesso <code>UPDATE_VECTORS=1</code>) e verificati in Go e in TS (<code>packages/vaultcrypto-web/src/negative.test.ts</code>). Coprono tag alterato (primo e ultimo chunk), ciphertext e salt alterati, <code>chunk_size</code> alterato, troncamento al confine di chunk e dentro un tag, primo chunk rimosso, chunk riordinati/duplicati/aggiunti, dati in coda, magic/versione/chunk size non validi (zero, oltre il massimo), AAD sbagliata (vault, file), VMK sbagliata, token di path alterati/di altro vault/prefisso sconosciuto/base64 invalido, token <code>enc2</code> alterati, di un altro file (<code>file_id</code> scambiato) o di un altro vault, <code>enc2</code> rietichettato <code>enc1</code> (downgrade) ed <code>enc1</code> rietichettato <code>enc2</code>, <code>enc2</code> troncati o non base64url, envelope alterati, KEK sbagliata, lunghezza errata, envelope v2 aperti per un altro vault, con <code>kind</code> scambiato o sconosciuto, con byte di versione alterato, troncati a 60 byte o privati del byte di versione (downgrade), con tag alterato o byte in coda, 10 casi di KDF fuori range, 5 recovery key malformate. Ogni vettore dichiara la classe di errore (<code>decrypt</code>, <code>format</code>) oppure <code>any</code> dove le due implementazioni rifiutano ma classificano diversamente (dati in coda più corti di un tag: in TS è errore di formato, in Go è errore di autenticazione perché il chunk precedente viene autenticato per primo). <strong>Entrambe rifiutano sempre.</strong></li><li><strong>Politica della passphrase</strong>: <code>shared/conformance/passphrase/policy.json</code> (passphrase, esito, motivo; anche forme NFD e testi non latini) è eseguito da <code>apps/desktop/internal/crypto/policy_test.go</code> e da <code>packages/workbench/src/sync/strength.test.ts</code>: il core e il riscontro della UI accettano e rifiutano le stesse passphrase per lo stesso motivo. Contiene solo casi lontani dal limite, perché i dizionari dei due stimatori non sono identici (§4).</li><li><strong>Verifica</strong> (nessun servizio di CI, ADR-0036): i test Go e TS sui vettori girano in <code>task ci</code> (<code>test-go</code>, <code>test-ts</code>). La riproducibilità dei vettori, che prima controllava il job <code>crypto-vectors</code> di <code>security.yml</code> (rimosso nella 1.2.2), si verifica a mano prima di un rilascio: rigenerare come sotto e controllare che <code>git diff --exit-code shared/conformance/crypto</code> non mostri differenze.</li><li><strong>Rigenerare</strong>: <code>cd shared/go &amp;&amp; UPDATE_VECTORS=1 go test -run &#39;TestVectors|TestNegativeVectors&#39; ./vaultcrypto/</code>, poi eseguire i test TS e committare i JSON. Un cambio dei vettori positivi è un cambio di formato e richiede una nuova versione (<code>NDS2</code>).</li></ul><h2 id="_10-checklist-per-il-revisore" tabindex="-1">10. Checklist per il revisore <a class="header-anchor" href="#_10-checklist-per-il-revisore" aria-label="Permalink to &quot;10. Checklist per il revisore&quot;">​</a></h2><ul><li>[ ] Ogni chiave ha un solo uso e una etichetta HKDF distinta (<code>keys.go</code> righe <code>info*</code>). Nessuna chiave deriva da un&#39;altra di livello inferiore.</li><li>[ ] Nessun riuso di nonce: blob (nuova salt → nuova <code>K_file</code> per cifratura; contatore per chunk), path (nonce casuale, una chiave), wrap (nonce casuale, KEK per valore unico; l&#39;upgrade a v2 ri-cifra la stessa VMK sotto la stessa KEK con un nonce nuovo).</li><li>[ ] Envelope v2 (§5.3): AAD con <code>vault_id</code> e <code>kind</code>, byte di versione, rifiuto di lunghezze diverse da 60/61, impossibilità di downgrade; pinning per tipo in <code>apps/desktop/internal/sync/manager_ops.go</code>; scrittura v1/v2 governata da <code>features.envelope_v2</code> (<code>apps/desktop/internal/crypto/manager.go</code>, <code>writeV2</code>).</li><li>[ ] Politica della passphrase nel core (§4): <code>crypto.ValidatePassphrase</code> su ogni binding che imposta una passphrase nuova (<code>LinkNew</code> privato, <code>ChangePassphrase</code>, <code>SetPassphrase</code>) e in <code>NewMaterial</code>/<code>NewPassphraseEnvelope</code>; nessun controllo sulle passphrase esistenti (sblocco, verifica, recovery key, upgrade v2); fixture comuni in <code>shared/conformance/passphrase/policy.json</code>.</li><li>[ ] Normalizzazione NFC della passphrase e ordine dei tentativi in apertura (§5.4): nessuna forma provata oltre a NFC, input esatto e NFD; il ri-avvolgimento degli envelope legacy avviene solo con il flag acceso.</li><li>[ ] Token di path <code>enc2</code> (§5.2, ADR-0042): AAD con <code>vault_id</code> e <code>file_id</code>, nessuna apertura incrociata tra versioni, <code>hmac1</code> invariato; pin di vault, di file e pin forte in <code>apps/desktop/internal/sync/pull.go</code> (<code>clearPath</code>, <code>pinPathV2</code>, <code>loadPathPins</code>, <code>writePathV2</code>); scrittura e migrazione governate da <code>features.path_v2</code>; migrazione e condizioni del pin forte in <code>apps/desktop/internal/sync/pathmigrate.go</code> (<code>migrationOp</code>, <code>strongPin</code>).</li><li>[ ] Igiene delle chiavi (§4): un solo <code>*Subkeys</code> per vault sbloccato, <code>Wipe</code> al blocco sotto <code>RWMutex</code>, rifiuto di sottochiavi azzerate (<code>ErrWiped</code>), azzeramento di KEK e copie della VMK nel gestore delle chiavi.</li><li>[ ] L&#39;AAD del blob copre vault, file, indice e ultimo chunk; confrontare con i casi di <code>negative-vectors.json</code>.</li><li>[ ] Gestione errori: nessuna differenza osservabile utile tra tag sbagliato e chiave sbagliata (<code>ErrDecrypt</code>); l&#39;output parziale della decifratura in streaming viene scartato dal chiamante (commento in <code>DecryptBlob</code>): verificare i chiamanti in <code>apps/desktop/internal/sync</code> e <code>packages/vaultcrypto-web/src/export.ts</code>.</li><li>[ ] Bound e minimi dei parametri Argon2id (client e server identici), tetto della calibrazione a 256 MiB (§6) e comportamento di <code>DeriveKEKPassphrase</code> con envelope ostili.</li><li>[ ] Confronti in tempo costante: checksum della recovery key (non segreto), tag GCM (libreria). Nessun confronto di segreti con <code>==</code> su stringhe.</li><li>[ ] Origine dell&#39;entropia: <code>crypto/rand</code> (Go), <code>crypto.getRandomValues</code> (browser, <code>bytes.ts</code>).</li><li>[ ] Gestione della VMK in memoria e su disco: keychain del SO (desktop), nessuna persistenza in <code>localStorage</code>/IndexedDB nella Web UI (<code>packages/vaultcrypto-web</code>, <code>web/src/export</code>).</li><li>[ ] Argon2id in WASM (<code>hash-wasm</code>): versione bloccata in <code>yarn.lock</code>, richiede <code>&#39;wasm-unsafe-eval&#39;</code> nella CSP, nessun <code>unsafe-eval</code>.</li><li>[ ] Il server non ha percorsi che restituiscano o registrino envelope, path o contenuto in chiaro (log, audit, metriche): grep di <code>wrapped_vmk</code> e <code>kdf</code> in <code>services/cloud/internal</code>.</li><li>[ ] Limiti di §8: confermare che siano accettabili per la 1.0 e come documentati all&#39;utente.</li></ul>`,43)])])}const h=o(n,[["render",r]]);export{v as __pageData,h as default};
